// ============================================================================
// KRATOS FSAE — DECODIFICADOR MULTIPROTOCOLO CAN BUS (MANUALES OFICIALES)
// ============================================================================
// 1. Energy Meter FSAE (Big Endian / Motorola, 500 kbps): IDs 0x10d, 0x40d, 0x60d, 0x30d, 0x30e
// 2. Orion BMS 2 (Big Endian / Motorola, 500 kbps): IDs 0x6B0, 0x6B1
// 3. Inversor BorgWarner / Cascadia Motion CM (Little Endian / Intel): IDs 0x0A2, 0x0A5, 0x0A6, 0x0A7
//
// Salida 1: Objeto estructurado para nodo InfluxDB y Monitor Debug
// Salida 2: Publicación paralela MQTT (kratos/telemetria/...)
// Salida 3: Escritura directa en Influx Line Protocol vía HTTP POST (/api/v2/write)

const payload = msg.payload || {};
const canId = (payload.canid !== undefined) ? payload.canid : msg.canid;
const rawData = payload.data || msg.data;

if (canId === undefined || !rawData) {
    return null;
}

const buf = Buffer.isBuffer(rawData) ? rawData : Buffer.from(rawData);
if (buf.length < 8) {
    return null;
}

const timestampMs = Date.now();
const timestampNs = BigInt(timestampMs) * 1000000n;
const hexId = "0x" + canId.toString(16).toLowerCase().padStart(3, "0");

const measurement = "telemetria_kratos";
let origen = null;
let endianness = "BE";
let fields = {};
let mqttMessages = [];

// ============================================================================
// BLOQUE 1: ENERGY METER OFICIAL FSAE (BIG ENDIAN / MOTOROLA)
// ============================================================================

// 1.1 ID 0x10d (269 dec): Measurement Message (20 ms, DLC=8, IEEE 754 float BE)
//     Bytes 0..3: Current [A]  -> buf.readFloatBE(0)
//     Bytes 4..7: Voltage [V]  -> buf.readFloatBE(4)
if (canId === 0x10D) {
    const current = Number(buf.readFloatBE(0).toFixed(3));
    const voltage = Number(buf.readFloatBE(4).toFixed(3));
    const power_kw = Number(((voltage * current) / 1000.0).toFixed(3));

    origen = "energy_meter";
    endianness = "BE";
    fields = {
        current: current,
        voltage: voltage,
        power_kw: power_kw,
        corriente: current,
        voltaje: voltage,
        potencia_kw: power_kw
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/energy_meter/0x10d",
            payload: { current, voltage, power_kw, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        { topic: "kratos/telemetria/energy_meter/corriente", payload: current, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/voltaje", payload: voltage, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/potencia_kw", payload: power_kw, qos: 0, retain: false }
    );
}

// 1.2 ID 0x40d (1037 dec): Status Message (100 ms, DLC=8, Big Endian)
//     Byte 0, Bit 0: Violation (0 o 1)
//     Byte 0, Bit 1: Logging   (0 o 1, activo cuando TS > 60 V)
//     Bytes 1..3:    Reservados
//     Bytes 4..7:    Energy [Whr] en IEEE 754 float BE -> buf.readFloatBE(4)
else if (canId === 0x40D) {
    const statusByte = buf.readUInt8(0);
    const violation = statusByte & 0x01;
    const logging = (statusByte >> 1) & 0x01;
    const energy_whr = Number(buf.readFloatBE(4).toFixed(3));

    origen = "energy_meter";
    endianness = "BE";
    fields = {
        violation: violation,
        logging: logging,
        energy_whr: energy_whr,
        energia_wh: energy_whr
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/energy_meter/0x40d",
            payload: { violation, logging, energy_whr, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        { topic: "kratos/telemetria/energy_meter/energia", payload: energy_whr, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/estado", payload: { violation, logging }, qos: 0, retain: false }
    );
}

// 1.3 ID 0x60d (1549 dec): Temperature Message (250 ms, DLC=8)
//     Byte 0: bits 0..2 = mux_id; si mux_id === 0 -> bits 3..7 = num_sensors
//     Byte 1: Min Temp = buf.readUInt8(1) * 0.5 [°C]
//     Byte 2: Max Temp = buf.readUInt8(2) * 0.5 [°C]
else if (canId === 0x60D) {
    const byte0 = buf.readUInt8(0);
    const mux_id = byte0 & 0x07;

    if (mux_id !== 0) {
        return null;
    }

    const num_sensors = (byte0 >> 3) & 0x1F;
    const min_temp = Number((buf.readUInt8(1) * 0.5).toFixed(1));
    const max_temp = Number((buf.readUInt8(2) * 0.5).toFixed(1));

    origen = "energy_meter";
    endianness = "BE";
    fields = {
        mux_id: mux_id,
        num_sensors: num_sensors,
        min_temp: min_temp,
        max_temp: max_temp
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/energy_meter/0x60d",
            payload: { mux_id, num_sensors, min_temp, max_temp, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// 1.4 IDs 0x30d / 0x30e (781 / 782 dec): Señales de Equipo FSAE (sint32 BE)
else if (canId === 0x30D || canId === 0x30E) {
    const senal_1 = buf.readInt32BE(0);
    const senal_2 = buf.readInt32BE(4);

    origen = "equipo_fsae";
    endianness = "BE";
    fields = {
        senal_1: senal_1,
        senal_2: senal_2
    };

    mqttMessages.push(
        {
            topic: `kratos/telemetria/equipo/${hexId}`,
            payload: { senal_1, senal_2, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// ============================================================================
// BLOQUE 2: ORION BMS (BIG ENDIAN / MOTOROLA @ 500 kbps)
// ============================================================================

// 2.1 ID 0x6B0 (1712 dec): Estado del Pack BMS (Big Endian)
//     Bytes 0..1: Pack Current               -> buf.readInt16BE(0) * 0.1 [A]
//     Bytes 2..3: Pack Instantaneous Voltage -> buf.readUInt16BE(2) * 0.1 [V]
//     Byte  4:    Pack SOC                   -> buf.readUInt8(4) * 0.5 [%]
//     Byte  5:    High Temperature           -> buf.readInt8(5) [°C]
//     Byte  6:    Low Temperature            -> buf.readInt8(6) [°C]
//     Byte  7:    Relay / Fault Status       -> buf.readUInt8(7)
else if (canId === 0x6B0) {
    const pack_current = Number((buf.readInt16BE(0) * 0.1).toFixed(2));
    const pack_voltage = Number((buf.readUInt16BE(2) * 0.1).toFixed(2));
    const soc = Number((buf.readUInt8(4) * 0.5).toFixed(1));
    const temp_max = buf.readInt8(5);
    const temp_min = buf.readInt8(6);
    const relay_fault_status = buf.readUInt8(7);

    origen = "orion_bms";
    endianness = "BE";
    fields = {
        pack_current: pack_current,
        pack_voltage: pack_voltage,
        soc: soc,
        temp_max: temp_max,
        temp_min: temp_min,
        relay_fault_status: relay_fault_status
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/bms/estado",
            payload: {
                pack_current,
                pack_voltage,
                soc,
                temp_max,
                temp_min,
                relay_fault_status,
                id_can: hexId,
                timestamp: timestampMs
            },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/bms/0x6b0",
            payload: { pack_current, pack_voltage, soc, temp_max, temp_min, relay_fault_status, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        { topic: "kratos/telemetria/bms/temperatura", payload: temp_max, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/soc", payload: soc, qos: 0, retain: false }
    );
}

// 2.2 ID 0x6B1 (1713 dec): Límites de Corriente y Celdas BMS (Big Endian)
//     Bytes 0..1: Pack DCL (Discharge Current Limit) -> buf.readUInt16BE(0) [A]
//     Bytes 2..3: Pack CCL (Charge Current Limit)    -> buf.readUInt16BE(2) [A]
//     Bytes 4..5: High Cell Voltage                  -> buf.readUInt16BE(4) * 0.0001 [V]
//     Bytes 6..7: Low Cell Voltage                   -> buf.readUInt16BE(6) * 0.0001 [V]
else if (canId === 0x6B1) {
    const pack_dcl = buf.readUInt16BE(0);
    const pack_ccl = buf.readUInt16BE(2);
    const high_cell_voltage = Number((buf.readUInt16BE(4) * 0.0001).toFixed(4));
    const low_cell_voltage = Number((buf.readUInt16BE(6) * 0.0001).toFixed(4));

    origen = "orion_bms";
    endianness = "BE";
    fields = {
        pack_dcl: pack_dcl,
        pack_ccl: pack_ccl,
        high_cell_voltage: high_cell_voltage,
        low_cell_voltage: low_cell_voltage
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/bms/limites_celdas",
            payload: {
                pack_dcl,
                pack_ccl,
                high_cell_voltage,
                low_cell_voltage,
                id_can: hexId,
                timestamp: timestampMs
            },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/bms/0x6b1",
            payload: { pack_dcl, pack_ccl, high_cell_voltage, low_cell_voltage, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// ============================================================================
// BLOQUE 3: INVERSOR BORGWARNER / CASCADIA MOTION (LITTLE ENDIAN / INTEL)
// ============================================================================

// 3.1 ID 0x0A2 (162 dec): Temperaturas Internas y de Motor EMRAX (Little Endian)
//     Bytes 0..1: Inverter Module Temperature -> buf.readInt16LE(0) * 0.1 [°C]
//     Bytes 4..5: Motor Temperature           -> buf.readInt16LE(4) * 0.1 [°C]
else if (canId === 0x0A2) {
    const inverter_temp = Number((buf.readInt16LE(0) * 0.1).toFixed(1));
    const motor_temp = Number((buf.readInt16LE(4) * 0.1).toFixed(1));

    origen = "inversor_borgwarner";
    endianness = "LE";
    fields = {
        inverter_temp: inverter_temp,
        motor_temp: motor_temp
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/inversor/temperaturas",
            payload: { inverter_temp, motor_temp, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/inversor/0x0a2",
            payload: { inverter_temp, motor_temp, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// 3.2 ID 0x0A5 (165 dec): Posición y Velocidad del Motor (Little Endian)
//     Bytes 2..3: Motor Speed -> buf.readInt16LE(2) [RPM]
else if (canId === 0x0A5) {
    const motor_speed_rpm = buf.readInt16LE(2);

    origen = "inversor_borgwarner";
    endianness = "LE";
    fields = {
        motor_speed_rpm: motor_speed_rpm
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/inversor/velocidad_motor",
            payload: { motor_speed_rpm, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/inversor/0x0a5",
            payload: { motor_speed_rpm, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// 3.3 ID 0x0A6 (166 dec): Corrientes del Inversor (Little Endian)
//     Bytes 6..7: DC Bus Current -> buf.readInt16LE(6) * 0.1 [A]
else if (canId === 0x0A6) {
    const dc_bus_current = Number((buf.readInt16LE(6) * 0.1).toFixed(2));

    origen = "inversor_borgwarner";
    endianness = "LE";
    fields = {
        dc_bus_current: dc_bus_current
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/inversor/corriente_dc",
            payload: { dc_bus_current, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/inversor/0x0a6",
            payload: { dc_bus_current, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
}

// 3.4 ID 0x0A7 (167 dec): Voltaje DC del Inversor (Little Endian)
//     Bytes 0..1: DC Bus Voltage -> buf.readInt16LE(0) * 0.1 [V]
else if (canId === 0x0A7) {
    const dc_bus_voltage = Number((buf.readInt16LE(0) * 0.1).toFixed(2));

    origen = "inversor_borgwarner";
    endianness = "LE";
    fields = {
        dc_bus_voltage: dc_bus_voltage
    };

    mqttMessages.push(
        {
            topic: "kratos/telemetria/inversor/voltaje_dc",
            payload: { dc_bus_voltage, id_can: hexId, timestamp: timestampMs },
            qos: 0,
            retain: false
        },
        {
            topic: "kratos/telemetria/inversor/0x0a7",
            payload: { dc_bus_voltage, timestamp: timestampMs },
            qos: 0,
            retain: false
        }
    );
} else {
    return null;
}

const tags = {
    origen: origen,
    id_can: hexId,
    endianness: endianness
};

// Construir cadena en Influx Line Protocol:
// telemetria_kratos,origen=<origen>,id_can=<id_can> campo1=val1,campo2=val2 <timestamp_ns>
const fieldStr = Object.entries(fields).map(([k, v]) => `${k}=${v}`).join(",");
const lineProtocol = `${measurement},origen=${origen},id_can=${hexId} ${fieldStr} ${timestampNs.toString()}`;

// Salida 1: Objeto para nodo InfluxDB y Monitor Debug
const influxNodeMsg = {
    measurement: measurement,
    lineProtocol: lineProtocol,
    payload: [
        fields,
        tags
    ]
};

// Salida 3: Escritura directa por HTTP POST a InfluxDB v2 API (/api/v2/write) con Line Protocol
const baseUrl = env.get("INFLUXDB_URL") || "http://influxdb:8086";
const token = env.get("INFLUXDB_TOKEN") || "kratos-fsae-telemetry-token-2026";
const org = env.get("INFLUXDB_ORG") || "kratos_fsae";
const bucket = env.get("INFLUXDB_BUCKET") || "telemetria_carro";

const influxHttpMsg = {
    method: "POST",
    url: `${baseUrl}/api/v2/write?org=${encodeURIComponent(org)}&bucket=${encodeURIComponent(bucket)}&precision=ns`,
    headers: {
        "Authorization": `Token ${token}`,
        "Content-Type": "text/plain; charset=utf-8"
    },
    payload: lineProtocol
};

return [influxNodeMsg, mqttMessages, influxHttpMsg];
